template <typename T>
struct format_arg_traits {
    using type = typename std::decay<T>::type;
};

template <std::size_t N>
struct format_arg_traits<char[N]> {
    using type = const char*;
};

template <std::size_t N>
struct format_arg_traits<const char[N]> {
    using type = const char*;
};

